package com.estoqueinteligente.report;
import java.math.BigDecimal;import java.util.*;import org.springframework.stereotype.Service;import com.estoqueinteligente.product.*;
@Service public class WhatsappMessageService{private static final BigDecimal MARGIN_FACTOR=new BigDecimal("1.30");private final ProductService products;public WhatsappMessageService(ProductService products){this.products=products;}public List<WhatsappMessageResponse> getMessages(){List<WhatsappMessageResponse> result=new ArrayList<>();for(ProductResponse p:products.findAll()){if(p.getStatus()==ProductStatus.VENCENDO)result.add(new WhatsappMessageResponse(p.getId(),p.getName(),"Promoção no mercado! "+p.getName()+" com condição especial por tempo limitado. Aproveite enquanto durar o estoque.","Produto próximo da validade"));if(p.getStatus()!=ProductStatus.VENCIDO&&hasGoodMargin(p))result.add(new WhatsappMessageResponse(p.getId(),p.getName(),"Oferta especial! "+p.getName()+" disponível em nosso mercado. Consulte valores e aproveite.","Produto com boa margem"));if(p.getQuantity()>p.getMinimumStock()*3)result.add(new WhatsappMessageResponse(p.getId(),p.getName(),"Temos "+p.getName()+" disponível em estoque. Chame no WhatsApp e confira.","Estoque alto"));}return result;}private boolean hasGoodMargin(ProductResponse p){return p.getSalePrice().compareTo(p.getCostPrice())>0&&p.getSalePrice().compareTo(p.getCostPrice().multiply(MARGIN_FACTOR))>=0;}}
